import type { SerializedStyles } from '@emotion/react';
import { css } from '@emotion/react';
import type { RadioGroupProps as AntDRadioGroupProps, RadioProps as AntDRadioProps } from 'antd';
import { Radio as AntDRadio } from 'antd';
import { forwardRef } from 'react';

import type { ComponentTheme, Theme } from '../../theme';
import { DesignSystemAntDConfigProvider, getAnimationCss } from '../DesignSystemProvider';
import { useDesignSystemTheme } from '../Hooks';
import type { DangerouslySetAntdProps, HTMLDataAttributes } from '../types';
import { importantify } from '../utils/css-utils';

const verticalGroupEmotionStyles = ({
  theme,
  clsPrefix,
  isBold,
}: {
  theme: Theme;
  clsPrefix: string;
  isBold: boolean;
}) =>
  css(
    importantify({
      display: 'flex',
      flexDirection: 'column',
      flexWrap: 'wrap',

      '& > label': {
        fontWeight: isBold ? theme.typography.typographyBoldFontWeight : 'normal',
        // TODO(FEINF-1496): Uncomment, removed for now to avoid impacting app with V2 changes
        // paddingBottom: theme.spacing.sm,
      },

      [`& > label + .${clsPrefix}-hint`]: {
        // TODO(FEINF-1496): Uncomment, removed for now to avoid impacting app with V2 changes
        // marginTop: `-${theme.spacing.sm}px`,
        marginBottom: theme.spacing.sm,
        paddingLeft: theme.spacing.lg,
      },
    })
  );

const radioOverrideEmotionStyles = ({
  theme,
  clsPrefix,
  classNamePrefix,
  isBold,
}: {
  theme: ComponentTheme;
  clsPrefix: string;
  classNamePrefix: string;
  isBold: boolean;
}): SerializedStyles =>
  css({
    '&&': {
      display: 'grid',
      gridTemplateRows: '[label] auto [hint] auto',
      gridAutoColumns: 'max-content',
      // TODO(FEINF-1496): Uncomment, removed for now to avoid impacting app with V2 changes
      // gridColumnGap: theme.spacing.md,
      gridColumnGap: theme.spacing.sm,
    },

    '& > label': {
      fontWeight: isBold ? theme.typography.typographyBoldFontWeight : 'normal',
      gridRow: 'label / label',
      marginRight: 0,
    },

    [`& > label + .${classNamePrefix}-hint`]: {
      display: 'inline-block',
      gridRow: 'hint / hint',
      paddingLeft: theme.spacing.lg,
    },

    [`.${clsPrefix}`]: {
      alignSelf: 'start',
      // Unchecked Styles
      [`> .${clsPrefix}-input + .${clsPrefix}-inner`]: {
        width: theme.spacing.md,
        height: theme.spacing.md,
        background: theme.colors.radioDefaultBackground,
        borderStyle: 'solid',
        borderColor: theme.colors.radioDefaultBorder,
        boxShadow: 'unset',
        transform: 'unset', // This prevents an awkward jitter on the border
        display: 'flex',
        justifyContent: 'center',
        alignItems: 'center',
        borderRadius: '50%',
        '&:after': {
          all: 'unset',
        },
      },
      // Hover
      [`&:not(.${clsPrefix}-disabled) > .${clsPrefix}-input:hover + .${clsPrefix}-inner`]: {
        borderColor: theme.colors.radioInteractiveHover,
        background: theme.colors.radioInteractiveHoverSecondary,
      },
      // Focus
      [`&:not(.${clsPrefix}-disabled)> .${clsPrefix}-input:focus + .${clsPrefix}-inner`]: {
        borderColor: theme.colors.primary,
      },
      // Active
      [`&:not(.${clsPrefix}-disabled)> .${clsPrefix}-input:active + .${clsPrefix}-inner`]: {
        borderColor: theme.colors.radioInteractivePress,
        background: theme.colors.radioInteractivePressSecondary,
      },
      // Disabled
      [`&.${clsPrefix}-disabled > .${clsPrefix}-input + .${clsPrefix}-inner`]: {
        borderColor: `${theme.colors.radioDisabled}!important`, // Ant uses !important
      },

      // Checked Styles
      [`&.${clsPrefix}-checked`]: {
        '&:after': {
          border: 'unset',
        },
        [`> .${clsPrefix}-input + .${clsPrefix}-inner`]: {
          background: theme.colors.primary,
          borderColor: theme.colors.primary,
          '&:after': {
            content: `""`,
            borderRadius: theme.spacing.xs,
            backgroundColor: theme.colors.radioDefaultBackground,
            width: theme.spacing.xs,
            height: theme.spacing.xs,
          },
        },

        // Hover
        [`&:not(.${clsPrefix}-disabled) > .${clsPrefix}-input:hover + .${clsPrefix}-inner`]: {
          background: theme.colors.radioInteractiveHover,
          borderColor: theme.colors.radioInteractiveHover,
        },
        // Focus
        [`&:not(.${clsPrefix}-disabled) > .${clsPrefix}-input:focus-visible + .${clsPrefix}-inner`]: {
          background: theme.colors.primary,
          borderColor: theme.colors.primary,
          boxShadow: `0 0 0 1px ${theme.colors.radioDefaultBackground}, 0 0 0 3px ${theme.colors.primary}`,
        },
        // Active
        [`&:not(.${clsPrefix}-disabled) > .${clsPrefix}-input:active + .${clsPrefix}-inner`]: {
          background: theme.colors.radioInteractivePress,
          borderColor: theme.colors.radioInteractivePress,
        },
        // Disabled
        [`&.${clsPrefix}-disabled > .${clsPrefix}-input + .${clsPrefix}-inner`]: {
          background: `${theme.colors.radioDisabled}`,
          border: `2px solid ${theme.colors.radioDisabled}!important`, // !important inherited from ant
        },
      },
    },
    ...getAnimationCss(theme.options.enableAnimation),
  });

export const getRadioStyles = ({ theme, isBold }: { theme: Theme; isBold: boolean }): SerializedStyles => {
  const styles = {
    '&&': {
      fontWeight: isBold ? theme.typography.typographyBoldFontWeight : 'normal',
    },
  };

  return css(importantify(styles));
};

export interface RadioProps
  extends Omit<AntDRadioProps, 'prefixCls' | 'type' | 'skipGroup'>,
    DangerouslySetAntdProps<AntDRadioGroupProps>,
    HTMLDataAttributes {
  isBold?: boolean;
}

export interface RadioGroupProps
  extends Omit<AntDRadioGroupProps, 'optionType' | 'buttonStyle' | 'size' | 'prefixCls' | 'skipGroup'>,
    DangerouslySetAntdProps<AntDRadioGroupProps>,
    HTMLDataAttributes {
  isBold?: boolean;
}

export interface RadioInterface extends React.FC<RadioProps> {
  Group: typeof VerticalGroup;
  HorizontalGroup: typeof HorizontalGroup;
}

const DuboisRadio = forwardRef<HTMLElement, RadioProps>(function Radio(
  { dangerouslySetAntdProps, isBold = false, ...props },
  ref
) {
  const { theme } = useDesignSystemTheme();
  return (
    <DesignSystemAntDConfigProvider>
      <AntDRadio css={getRadioStyles({ theme, isBold })} {...props} {...dangerouslySetAntdProps} ref={ref} />
    </DesignSystemAntDConfigProvider>
  );
});

const StyledRadioGroup = forwardRef<HTMLDivElement, RadioGroupProps>(function StyledRadioGroup(
  { dangerouslySetAntdProps, isBold = false, ...props }: RadioGroupProps,
  ref
) {
  const { theme, getPrefixedClassName, classNamePrefix } = useDesignSystemTheme();
  const clsPrefix = getPrefixedClassName('radio');

  return (
    <DesignSystemAntDConfigProvider>
      <AntDRadio.Group
        {...props}
        css={radioOverrideEmotionStyles({ theme, clsPrefix, classNamePrefix, isBold })}
        {...dangerouslySetAntdProps}
        ref={ref}
      />
    </DesignSystemAntDConfigProvider>
  );
});

const VerticalGroup: React.FC<RadioGroupProps> = forwardRef<HTMLDivElement, RadioGroupProps>(function VerticalGroup(
  { dangerouslySetAntdProps, isBold = false, ...props },
  ref
) {
  const { theme, classNamePrefix } = useDesignSystemTheme();

  return (
    <StyledRadioGroup
      css={verticalGroupEmotionStyles({ theme, clsPrefix: classNamePrefix, isBold })}
      {...props}
      ref={ref}
      {...dangerouslySetAntdProps}
    />
  );
});

const HorizontalGroup: React.FC<RadioGroupProps> = forwardRef<HTMLDivElement, RadioGroupProps>(function HorizontalGroup(
  { dangerouslySetAntdProps, ...props },
  ref
) {
  return <StyledRadioGroup {...props} ref={ref} {...dangerouslySetAntdProps} />;
});

// Note: We are overriding ant's default "Group" with our own.
const RadioNamespace = /* #__PURE__ */ Object.assign(DuboisRadio, { Group: VerticalGroup, HorizontalGroup });
export const Radio: RadioInterface = RadioNamespace;

// TODO: I'm doing this to support storybook's docgen;
// We should remove this once we have a better storybook integration,
// since these will be exposed in the library's exports.
// We should ideally be using __Group instead of __VerticalGroup, but that exists under Checkbox too and conflicts, therefore
// we show a wrong component name in "Show code" in docs, fix included in story to replace this with correct name
export const __INTERNAL_DO_NOT_USE__VerticalGroup = VerticalGroup;
export const __INTERNAL_DO_NOT_USE__HorizontalGroup = HorizontalGroup;
